mapper.select:
select distinct sm.id as storageMaterialId, sm.no as materialNo, sm.material_position_id, sm.available_quantity as quantity, b.material_batch_no, sm.unit_id, sm.unit_extend_id, b.expired_date, b.material_id, p.position as materialPositionName, p.code as materialPositionCode, b.hydration, b.no_hydration_content, b.supplier, b.producer from bm_storage_material sm left join bm_cargo_position p on sm.material_position_id = p.id left join bm_resource_permission rp on rp.resource_id = p.id left join bm_storage_material_batch b on sm.storage_material_batch_id = b.id where sm.available_quantity != 0 and b.available = true
and sm.material_id = #{materialId}
and rp.dept_id in
#{item}
order by b.material_batch_no ASC, CAST(sm.no AS UNSIGNED) ASC

select.where:
bm_storage_material_batch.is_deleted = 0 and bm_material.is_deleted = 0 and bm_storage_material.is_deleted = 0
and bm_storage_material.id in
#{item}

mapper.select:
SELECT distinct bm_storage_material_batch.id AS materialBatchId, bm_storage_material_batch.material_id, sum(bm_storage_material.reserve_quantity) as reserveQuantity, bm_storage_material.unit_id, bm_storage_material_batch.material_batch_no, bm_storage_material_batch.hydration, bm_storage_material_batch.no_hydration_content, bm_storage_material_batch.supplier, bm_storage_material_batch.producer, bm_storage_material_batch.expired_date, bm_storage_material_batch.factory_batch_no, bm_storage_material_batch.original_batch_no, bm_storage_material_batch.report_no, bm_storage_material_batch.licence_no, bm_material.merge_code FROM bm_storage_material_batch LEFT JOIN bm_storage_material ON bm_storage_material.storage_material_batch_id = bm_storage_material_batch.id left join bm_material on bm_material.id = bm_storage_material_batch.material_id where bm_storage_material.id in
#{id}
GROUP BY bm_storage_material_batch.id order by
#{id}

select distinct bm_storage_material.* from bm_storage_material left join bm_storage_material_reserve on bm_storage_material_reserve.storage_material_id = bm_storage_material.id where bm_storage_material_reserve.is_deleted = 0 and bm_storage_material.storage_material_batch_id in
#{id}
and bm_storage_material_reserve.batch_id = #{productPlanId}
